INSERT INTO artigos (slug,status,tipo,titulo,titulo_original,autor,autor_citacao,afiliacao,tradutor,periodico,volume,numero,ano,mes,paginas_original,editora_original,url_original,area,tema,tema_en,resumo,resumo_en,resumo_editorial,palavras_chave,direitos,pdf_url,pdf_paginas,capa_url,publicado_em) VALUES
('moberly-deus-mente-profetas','publicado','traducao','Deus mente aos seus profetas? A história de Micaías ben Imlá como estudo de caso','Does God Lie to His Prophets? The Story of Micaiah ben Imlah as a Test Case','R. W. L. Moberly','MOBERLY, R. W. L.','Durham University','Gabriel Cantarino','Harvard Theological Review','96','1','2003','jan.','1–23','Cambridge University Press / Harvard Divinity School','https://doi.org/10.1017/S0017816003000312','Antigo Testamento','Micaías ben Imlá · discernimento profético','Micaiah ben Imlah · prophetic discernment','O artigo oferece uma leitura detalhada de 1 Reis 22:1–38, a história de Micaías ben Imlá, concentrando-se na dificuldade moral e teológica da segunda visão do profeta, em que YHWH parece patrocinar um espírito mentiroso para enganar o rei de Israel. Moberly sustenta que a narrativa ilustra o conflito entre a obstinação do rei, expressa por seus profetas, e a integridade de Micaías, que adverte o rei do perigo e lhe dá ocasião de mudar de rumo; a integridade aparece, assim, como a chave do discernimento entre vozes proféticas que falam em nome do mesmo Deus. Em seguida, responde à análise de fontes de Simon De Vries, defendendo a coerência literária do relato, e discute os problemas histórico-traditivos, sugerindo que a identificação do rei com Acabe talvez não seja original. Por fim, propõe o livro de Jeremias como o melhor modelo bíblico para interpretar a história.','The article offers a close reading of 1 Kings 22:1–38, the story of Micaiah ben Imlah, focusing on the moral and theological difficulty of the prophet’s second vision, in which YHWH appears to sponsor a lying spirit to deceive the king of Israel. Moberly argues that the narrative illustrates the conflict between the king’s willfulness, voiced by his prophets, and the integrity of Micaiah, who warns the king of his danger and gives him the opportunity to change course; integrity thus emerges as the key to discernment between prophetic voices that speak in the name of the same God. He then responds to Simon De Vries’s source analysis, defending the literary coherence of the account, and discusses the tradition-historical problems, suggesting that the identification of the king with Ahab may not be original. Finally, he proposes the book of Jeremiah as the best biblical model for interpreting the story.',1,'["Micaías ben Imlá", "1 Reis 22", "falsa profecia", "espírito mentiroso", "discernimento profético", "Acabe", "conselho divino", "Jeremias", "História Deuteronomista"]','Publicado com autorização de R. W. L. Moberly (20/11/2026). Os direitos do texto original pertencem a R. W. L. Moberly. Tradução para o português © 2026 Gabriel Cantarino / The Prophetic Voices, para fins de estudo, sem fins lucrativos.','/artigos/moberly-2003-deus-mente-profetas.pdf',30,'/artigos/moberly-2003-deus-mente-profetas-capa.jpg','2026-11-21 15:28:00');
